{
    test_md5();
    test_aka_vectors();
    test_b64();
    test_sec_agree();
    test_build_first();
    test_response_parse();
    test_sdp_and_tcp_frame();
    test_route_set();
    test_ack_echoes_dialog_uris();
    test_bye_echoes_dialog_uris();
    test_pcscf_candidates();
    if (g_fail) {
        printf("\n%d TEST(S) FAILED\n", g_fail);
        return 1;
    }
    printf("\nALL HOST TESTS PASSED\n");
    return 0;
}
